}

// isLegacyMajor checks if the given major release number indicates a legacy distro.
func isLegacyMajor(major int) bool {
	return major < 6 // RHEL/CentOS/Oracle below 6, Fedora below 9
}

func isRunningKernel(pack models.Package, family string, release string, kernel models.Kernel) (isKernel, running bool) {
	switch family {
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		if pack.Name == "kernel-default" {
			// Remove the last period and later because uname don't show that.
			ss := strings.Split(pack.Release, ".")
			rel := strings.Join(ss[0:len(ss)-1], ".")
			ver := fmt.Sprintf("%s-%s-default", pack.Version, rel)
			return true, kernel.Release == ver
		}
		return false, false

	case constant.RedHat, constant.Oracle, constant.CentOS, constant.Alma, constant.Rocky, constant.Amazon, constant.Fedora:
		if !isKernelPackage(pack.Name) {
			return false, false
		}

		packIsDebug := isDebugKernelPackage(pack.Name)
		kernelIsDebug := strings.HasSuffix(kernel.Release, "+debug")

		// Debug running kernel must match only debug-named packages
		// Non-debug running kernel must match only non-debug packages
		if packIsDebug != kernelIsDebug {
			return true, false
		}

		major, err := strconv.Atoi(util.Major(release))
		if err != nil {
			major = 0
		}

		if major >= 6 {
			// Modern Red Hat-family (RHEL 6+, Alma, Rocky, Amazon, Fedora 9+)
			// Format: <Version>-<Release>.<Arch> or <Version>-<Release>.<Arch>+debug
			expectedRelease := fmt.Sprintf("%s-%s.%s", pack.Version, pack.Release, pack.Arch)
			if packIsDebug {
				expectedRelease += "+debug"
			}
			return true, kernel.Release == expectedRelease
		} else {
			// Legacy releases (RHEL/CentOS/Oracle < 6, Fedora < 9)
			// Format: <Version>-<Release> or <Version>-<Release>debug
			expectedRelease := fmt.Sprintf("%s-%s", pack.Version, pack.Release)
			if packIsDebug {
				expectedRelease += "debug"
			}
			return true, kernel.Release == expectedRelease
		}

	default:
		logging.Log.Warnf("Reboot required is not implemented yet: %s, %v", family, kernel)
	}
	return false, false
}

// EnsureResultDir ensures the directory for scan results
func EnsureResultDir(resultsDir string, scannedAt time.Time) (currentDir string, err error) {
	jsonDirName := scannedAt.Format("2006-01-02T15-04-05-0700")
	if resultsDir == "" {
		wd, _ := os.Getwd()
		resultsDir = filepath.Join(wd, "results")
	}
	jsonDir := filepath.Join(resultsDir, jsonDirName)
	if err := os.MkdirAll(jsonDir, 0700); err != nil {
		return "", xerrors.Errorf("Failed to create dir: %w", err)
	}
	return jsonDir, nil
}

func writeScanResults(jsonDir string, results models.ScanResults) error {
	ws := []reporter.ResultWriter{reporter.LocalFileWriter{
		CurrentDir: jsonDir,
		FormatJSON: true,
	}}
	for _, w := range ws {
		if err := w.Write(results...); err != nil {
			return xerrors.Errorf("Failed to write summary: %s", err)
		}
	}

	reporter.StdoutWriter{}.WriteScanSummary(results...)

	errServerNames := []string{}
	for _, r := range results {
		if 0 < len(r.Errors) {
			errServerNames = append(errServerNames, r.ServerName)
		}
	}
	if 0 < len(errServerNames) {
		return fmt.Errorf("An error occurred on %s", errServerNames)
	}
	return nil
}
